#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node* prev;
};

void pushFront(Node** headRef, int newData) {
    Node* newNode = new Node();
    newNode->data = newData;
    newNode->next = *headRef;
    newNode->prev = nullptr;
    if (*headRef != nullptr) {
        (*headRef)->prev = newNode;
    }
    *headRef = newNode;
}

void pushBack(Node** headRef, int newData) {
    Node* newNode = new Node();
    newNode->data = newData;
    newNode->next = nullptr;
    if (*headRef == nullptr) {
        newNode->prev = nullptr;
        *headRef = newNode;
        return;
    }
    Node* last = *headRef;
    while (last->next != nullptr) {
        last = last->next;
    }
    last->next = newNode;
    newNode->prev = last;
}

void printBothWays(Node* head) {
    Node* last = nullptr;
    Node* cur = head;
    while (cur != nullptr) {
        cout << cur->data << " ";
        last = cur;
        cur = cur->next;
    }
    cout << "| ";
    while (last != nullptr) {
        cout << last->data << " ";
        last = last->prev;
    }
    cout << endl;
}

void freeList(Node* head) {
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

int main() {
    Node* head = nullptr;
    pushBack(&head, 20);
    pushFront(&head, 10);
    pushBack(&head, 30);
    printBothWays(head);
    freeList(head);
    return 0;
}
